import React from 'react';
import type { FC } from 'react';
import { match } from 'variant';
import { Spinner, useAsync } from '@wix/cli-ui-kit';
import { OpenBrowser } from './OpenBrowser.js';
import { useWebSocketServer } from './useWebSocketServer.js';
import { getAppInstallerUrl } from './app-installer-url.js';

interface Props {
  appId: string;
  onSubmit: (siteId: string) => void;
  onError: (error: unknown) => void;
}

export const AppInstaller: FC<Props> = ({ appId, onSubmit, onError }) => {
  const createWsServer = useWebSocketServer(onError);

  const { status } = useAsync(
    async () => {
      const wsServer = await createWsServer();
      const { port } = await wsServer.serve();

      wsServer.onConnect(async ({ siteId }) => {
        onSubmit(siteId);
      });

      return getAppInstallerUrl({ wsPort: port, appId });
    },
    [],
    { onError }
  );

  return match(status, {
    Error: () => null,
    Loading: () => <Spinner text="Loading..." />,
    Success: ({ result: appInstallerUrl }) => (
      <OpenBrowser url={appInstallerUrl} />
    ),
  });
};
