import { getAppMarketUrl } from './app-marker-url.js';
import { getRedirectServiceUrl } from './redirect-service-url.js';

export function getAppInstallerUrl({
  wsPort,
  appId,
}: {
  wsPort: number;
  appId: string;
}): string {
  const postInstallationUrl = new URL(
    'https://dev.wix.com/wix-cli/app-installation-success/'
  );
  postInstallationUrl.searchParams.set('wsPort', wsPort.toString());

  return getAppMarketUrl({
    appId,
    postInstallationUrl: postInstallationUrl.toString(),
  });
}

export function getSiteAppInstallerUrl({
  appId,
  siteId,
}: {
  appId: string;
  siteId: string;
}): string {
  /**
   * `appId` and `siteId` are omitted — app market will append them to
   * `postInstallationUrl` once the user selects a site during installation
   */
  const redirectUrl = getRedirectServiceUrl({ platform: 'dashboard' });

  return getAppMarketUrl({
    appId,
    siteId,
    postInstallationUrl: redirectUrl.toString(),
  });
}
