import { useAsyncCallback } from '@wix/cli-ui-kit';
import { createAppInstallerServer } from '@wix/cli-app-installer-comm-api';

export function useWebSocketServer(onError: (error: unknown) => void) {
  const { execute } = useAsyncCallback(
    async ({ signal }) => {
      const server = createAppInstallerServer();

      signal.onabort = () => {
        server.close().catch(onError);
      };

      return server;
    },
    { onError }
  );

  return execute;
}
