import React from 'react';
import type { FC } from 'react';
import { Text, Key, useInput } from '@wix/cli-ui-kit';
import { openBrowser } from '@wix/user-browser';

interface Props {
  url: string;
}

export const OpenBrowser: FC<Props> = ({ url }) => {
  useInput(async (input, key) => {
    if (key.return) {
      await openBrowser(url);
    }
  });

  return (
    <>
      <Text>Your new app needs to be installed on the development site</Text>
      <Text>
        Press <Key value="Enter" /> to install the app in your browser
      </Text>
    </>
  );
};
